'use strict';
const C=window.AKPOL_CONFIG,root=document.querySelector('#root'),modal=document.querySelector('#modal');
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>new Intl.NumberFormat('pl-PL',{maximumFractionDigits:3}).format(Number(x||0));
const money=x=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(Number(x||0));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Warsaw'}).format(new Date());
const stamp=x=>x?new Date(x).toLocaleString('pl-PL'):'';
const states={ready:'Sprawna',reserved:'Zarezerwowana',repair:'W naprawie',damaged:'Uszkodzona',scrapped:'Złom'};
const statuses={todo:'Do zrobienia',doing:'W trakcie',waiting:'Czeka',done:'Gotowe'};
const operations={mount:'Montaż',unmount:'Demontaż',move:'Przesunięcie',state:'Stan / serwis',receive:'Przyjęcie',issue:'Wydanie',transfer:'Przesunięcie',reserve:'Rezerwacja',release:'Zwolnienie rezerwacji',damage:'Uszkodzenie'};
const pages={dashboard:['Pulpit zespołu','▦'],vehicles:['Samochody','◇'],parts:['Części i przebiegi','⚙'],stock:['Magazyn i normalia','▤'],movements:['Ruchy magazynowe','⇄'],trips:['Przejazdy','↗'],service:['Serwis i limity','◷'],shortages:['Braki i zakupy','!'],board:['Tablica ekipy','▥'],notifications:['Powiadomienia','◉'],expenses:['Wydatki','▧'],cash:['Zaliczki i zwroty','↔'],settlements:['Rozliczenia','∑'],rallies:['Rajdy','⚑'],members:['Zespół i dostęp','♟'],settings:['Lokalizacje','⌂']};
let session=null,user=null,me=null,data={},page='dashboard',search='',loc='',board='',financeRally='',nav=false,busy=false,modalContext=null,lastSync='',refreshPromise=null;
let refreshTokenPromise=null;
const manager=()=>me?.role==='manager';
const lists=['team_members','locations','vehicle_totals','rallies','rally_budgets','products','stock','part_totals','stock_minima','trips','part_usage','movements','boards','tasks','comments','notifications','expenses','cash_entries','documents','shortages'];
const rows=t=>data[t]||[];
const find=(t,id)=>rows(t).find(x=>x.id===id);
const name=(t,id,key='name')=>find(t,id)?.[key]||'—';
const partName=id=>{let p=find('part_totals',id);return p?`${p.serial} · ${name('products',p.product_id)}`:'—'};
function toast(t,err=false){const el=document.querySelector('#toast');el.textContent=t;el.className=err?'error':'';el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',7000)}
function saveSession(s){session=s;sessionStorage.removeItem('akpol-cloud-session');if(s)localStorage.setItem('akpol-cloud-session',JSON.stringify(s));else localStorage.removeItem('akpol-cloud-session')}
async function auth(path,body){const r=await fetch(C.url+'/auth/v1/'+path,{method:body?'POST':'GET',headers:{apikey:C.key,'Content-Type':'application/json',...(session?.access_token?{Authorization:'Bearer '+session.access_token}:{})},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.msg||j.error_description||j.message||'Błąd logowania');return j}
async function token(){if(!session)throw Error('Zaloguj się.');if(session.expires_at*1000<Date.now()+60000){if(!refreshTokenPromise)refreshTokenPromise=auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token}).then(s=>{saveSession(s);return s.access_token}).finally(()=>refreshTokenPromise=null);return refreshTokenPromise}return session.access_token}
async function request(path,opts={}){const tk=await token();const r=await fetch(C.url+path,{...opts,headers:{apikey:C.key,Authorization:'Bearer '+tk,...(opts.body&&!(opts.body instanceof File)?{'Content-Type':'application/json'}:{}),...opts.headers}});if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(j.message||j.error||'Operacja nie powiodła się ('+r.status+').')}return r}
async function query(table){let result=[];for(let start=0;;start+=1000){let r=await request('/rest/v1/'+table+'?select=*',{headers:{Range:`${start}-${start+999}`,'Range-Unit':'items'}});let j=await r.json();result.push(...j);if(j.length<1000)break}return result}
async function command(cmd,d){const r=await request('/rest/v1/rpc/akpol_command',{method:'POST',body:JSON.stringify({cmd,d})});return r.json()}
async function sync(renderAfter=true){if(refreshPromise)return refreshPromise;refreshPromise=(async()=>{const result=await Promise.all(lists.map(query));let next=Object.fromEntries(lists.map((t,i)=>[t,result[i]]));let own=next.team_members.find(m=>m.email===user.email.toLowerCase()&&m.active);if(!own)throw Error('Twoje konto nie ma aktywnego dostępu do zespołu. Manager musi dodać ten sam e-mail w zakładce Zespół.');data=next;me=own;lastSync=new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});if(!board||!find('boards',board))board=rows('boards')[0]?.id||'';if(renderAfter)render()})().finally(()=>refreshPromise=null);return refreshPromise}
function badge(label,type=''){return `<span class="badge ${type}">${E(label)}</span>`}
function stateBadge(s){return badge(states[s]||s,s==='ready'?'green':s==='reserved'?'yellow':s==='repair'?'blue':'red')}
function finBadge(s){return badge({approved:'Zatwierdzony',pending:'Do akceptacji',rejected:'Do poprawy'}[s],s==='approved'?'green':s==='pending'?'yellow':'red')}
function btn(label,action,id='',style=''){return `<button type="button" class="btn ${style}" data-act="${action}" data-id="${E(id)}">${label}</button>`}
function navbtn(p){const unread=p==='notifications'?rows('notifications').filter(x=>!x.seen).length:p==='shortages'?short().filter(x=>Number(x.missing)>0).length:0;return `<button class="nav ${page===p?'active':''}" data-page="${p}"><i>${pages[p][1]}</i>${pages[p][0]}${unread?' <span class="badge red">'+unread+'</span>':''}</button>`}
function render(){if(!me)return;const hide=['members','settings'];root.innerHTML=`<div class="layout"><aside class="side ${nav?'open':''}"><div class="brand"><div class="mark">AK</div><div><b>AKPOL</b><span>RALLY TEAM</span></div></div><div class="group">Operacje</div>${['dashboard','vehicles','parts','stock','movements','trips','service','shortages'].map(navbtn).join('')}<div class="group">Współpraca</div>${['board','notifications'].map(navbtn).join('')}<div class="group">Finanse i zespół</div>${['expenses','cash','settlements','rallies','members','settings'].filter(p=>manager()||!hide.includes(p)).map(navbtn).join('')}<div class="sidefoot"><b>ONE TEAM ONE GOAL</b><br>Magazyn · Samochody · Ekipa<br>Finanse pracownika są prywatne.<br>Wersja chmurowa 0.3</div></aside><div class="main"><header class="top"><div class="flex">${btn('☰','nav','','mobile')}<div><div class="eyebrow">AKPOL RECYKLING RALLY TEAM</div><h1>${pages[page][0]}</h1></div></div><div class="flex"><div class="topprofile"><b>${E(me.name)}</b><div class="statusline">${manager()?'Manager':'Członek zespołu'} · synchronizacja ${lastSync}</div></div>${btn('Odśwież','sync','','sm')}${btn('Hasło','password','','sm')}${btn('Wyloguj','logout','','sm')}</div></header><main class="content">${({dashboard,vehicles,parts,stock,movements,trips,service,shortages,board:boardPage,notifications,expenses,cash,settlements,rallies,members,settings}[page])()}</main></div></div>`}
function table(headers,entries,empty='Brak wpisów. Dodaj pierwszą pozycję.'){return entries.length?`<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${entries.map(c=>`<tr>${c.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">${empty}</div>`}
function filtered(arr,fn){return arr.filter(x=>!search||fn(x).toLowerCase().includes(search.toLowerCase()))}
function toolbar(extra=''){return `<div class="toolbar"><input id="search" aria-label="Szukaj" placeholder="Szukaj po nazwie, numerze…" value="${E(search)}">${extra}</div>`}
function locSelect(all=true){return `<select id="location-filter" aria-label="Lokalizacja">${all?'<option value="">Wszystkie lokalizacje</option>':''}${options(rows('locations').map(x=>[x.id,x.name]),loc)}</select>`}
function heading(title,desc,actions=''){return `<div class="spread head"><div><h2>${title}</h2><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function metric(label,value,desc){return `<div class="card"><div class="small muted">${label}</div><div class="metric">${value}</div><div class="small muted">${desc}</div></div>`}
function short(){return rows('shortages')}
function dueParts(){return rows('part_totals').filter(p=>{const pr=find('products',p.product_id);return pr?.limit_km>0&&p.km>=pr.limit_km*.80&&p.state!=='scrapped'})}
function dashboard(){const shortagesCount=short().filter(x=>x.missing>0).length,openTasks=rows('tasks').filter(x=>x.status!=='done');return `<div class="hero"><div><div class="eyebrow">ONE TEAM ONE GOAL</div><h2>Gotowość zespołu. W jednym miejscu.</h2><p>Sprawdź zapasy, przebiegi i zadania przed kolejnym wyjazdem. Każdy egzemplarz części zachowuje swoją historię — w aucie i na magazynie.</p></div>${btn('＋ Nowe zadanie','new-task','','lime')}</div><div class="grid four">${metric('Samochody',rows('vehicles').length||rows('vehicle_totals').length,'Karty aut i zamontowane części')}${metric('Egzemplarze części',rows('part_totals').length,rows('part_totals').filter(x=>x.vehicle_id).length+' zamontowanych')}${metric('Braki magazynowe',shortagesCount,shortagesCount?'Pozycje poniżej minimum':'Zapasy zgodne z ustalonym minimum')}${metric('Otwarte zadania',openTasks.length,openTasks.filter(x=>x.due&&x.due<today()).length+' po terminie')}</div><div class="grid two section"><section class="card">${heading('Wymaga uzupełnienia','Sprawny, niezarezerwowany zapas',btn('Wszystkie braki','go-shortages','','sm'))}${shortageTable(short().filter(x=>x.missing>0).slice(0,5))}</section><section class="card">${heading('Twoje zadania','Najbliższe terminy',btn('Otwórz tablicę','go-board','','sm'))}${openTasks.filter(x=>x.assignee_id===me.id).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,6).map(taskCard).join('')||'<div class="empty">Nie masz otwartych zadań.</div>'}</section></div><section class="card section">${heading('Limity części','Ostrzeżenie od 80% ustalonego limitu')}${table(['Część','Lokalizacja','Przebieg','Limit'],dueParts().slice(0,6).map(p=>[btn(E(partName(p.id)),'part-detail',p.id,'sm'),wherePart(p),num(p.km)+' km',badge(num(name('products',p.product_id,'limit_km'))+' km',p.km>=name('products',p.product_id,'limit_km')?'red':'yellow')]))}</section>`}
function wherePart(p){return p.vehicle_id?E(name('vehicle_totals',p.vehicle_id))+'<small>'+E(p.slot)+'</small>':E(name('locations',p.location_id))}
function mileage(p){return `<b>${num(p.km)} km</b><small>OS ${num(p.os)} · dojazdówki ${num(p.liaison)}<br>Test szybki ${num(p.fast)} · spokojny ${num(p.low)}<br>${num(p.hours)} mth</small>`}
function vehicles(){return heading('Samochody','Przebiegi wynikające z zapisanych przejazdów i stanu początkowego.',manager()?btn('＋ Dodaj samochód','new-vehicle','','primary'):'')+`<div class="grid three">${rows('vehicle_totals').map(v=>`<section class="card"><div class="eyebrow">${E(v.code)}</div><h2>${E(v.name)}</h2><div class="metric">${num(v.km)} <small>km</small></div>${mileage(v)}<div class="banner">Zamontowane części: <b>${rows('part_totals').filter(p=>p.vehicle_id===v.id).length}</b></div><div class="actions">${btn('Karta samochodu','vehicle-detail',v.id)}${btn('＋ Przejazd','new-trip',v.id,'primary')}</div></section>`).join('')||'<div class="card empty">Dodaj pierwszy samochód z jego początkowym przebiegiem.</div>'}</div>`}
function parts(){let arr=filtered(rows('part_totals'),p=>partName(p.id)+' '+p.note).filter(p=>!loc||p.location_id===loc);return heading('Części numerowane','Każdy egzemplarz ma własny numer, przebieg, stan i historię.',btn('＋ Przyjmij egzemplarz','new-part','','primary')+(manager()?btn('＋ Typ części','new-product'):'') )+`<section class="card">${toolbar(locSelect())}${table(['Egzemplarz / część','Miejsce','Przebieg','Stan','Akcje'],arr.map(p=>[`<b>${E(p.serial)}</b><small>${E(name('products',p.product_id))}</small>`,wherePart(p),mileage(p),stateBadge(p.state),btn('Karta / historia','part-detail',p.id,'sm')+btn('Operacja','part-action',p.id,'sm')]))}</section>`}
function stock(){const arr=filtered(rows('products'),p=>p.sku+' '+p.name+' '+p.spec);return heading('Magazyn części i normaliów','Ilości według lokalizacji i stanu. Przebiegi części znajdziesz w karcie egzemplarza.',manager()?btn('＋ Indeks magazynowy','new-product','','primary'):'')+`<section class="card">${toolbar(locSelect())}${table(['Indeks / nazwa','Specyfikacja','Dostępne','Zarezerwowane / inne','Minimum globalne','Akcje'],arr.map(p=>{let pp=rows('part_totals').filter(x=>x.product_id===p.id&&(!loc||x.location_id===loc)),st=rows('stock').filter(x=>x.product_id===p.id&&(!loc||x.location_id===loc));let available=p.serialized?pp.filter(x=>!x.vehicle_id&&x.state==='ready'&&(!p.limit_km||x.km<p.limit_km)).length:st.filter(x=>x.state==='ready').reduce((a,x)=>a+Number(x.quantity),0);let reserved=p.serialized?pp.filter(x=>x.state==='reserved').length:st.filter(x=>x.state==='reserved').reduce((a,x)=>a+Number(x.quantity),0);return [`<b>${E(p.name)}</b><small>${E(p.sku)} · ${p.serialized?'Numerowana':'Ilościowa'}</small>`,E(p.spec),`<b>${num(available)} ${E(p.unit)}</b>`,`Rezerwacja: ${num(reserved)}<small>${p.serialized?'W autach: '+pp.filter(x=>x.vehicle_id).length:'Uszkodzone: '+num(st.filter(x=>x.state==='damaged').reduce((a,x)=>a+Number(x.quantity),0))}</small>`,num(p.minimum)+' '+E(p.unit),`<div class="actions">${btn('Szczegóły','product-detail',p.id,'sm')}${btn(p.serialized?'＋ Egzemplarz':'Ruch magazynowy',p.serialized?'new-part':'stock-action',p.id,'sm')}${manager()?btn('Ustawienia','edit-product',p.id,'sm'):''}</div>`]}))}</section>`}
function movements(){return heading('Historia magazynu','Przyjęcia, wydania, przesunięcia, montaż, demontaż i zmiany stanu.')+`<section class="card">${toolbar()}${movementTable(filtered(rows('movements'),m=>name('products',m.product_id)+' '+partName(m.part_id)+' '+m.note))}</section>`}
function movementTable(arr){return table(['Kiedy / kto','Część / indeks','Operacja','Skąd → dokąd','Ilość / uwagi'],[...arr].sort((a,b)=>b.at.localeCompare(a.at)).map(m=>[`${stamp(m.at)}<small>${E(name('team_members',m.actor_id))}</small>`,E(m.part_id?partName(m.part_id):name('products',m.product_id)),E(operations[m.kind]||m.kind),E(name('locations',m.from_location))+' → '+E(name('locations',m.to_location))+(m.vehicle_id?'<small>'+E(name('vehicle_totals',m.vehicle_id))+'</small>':''),`${num(m.quantity)}<small>${E(m.note)}</small>`]))}
function trips(){return heading('Przejazdy i naliczanie kilometrów','Zapisuj jazdę przed demontażem części. Każdy wpis zachowuje listę zamontowanych egzemplarzy.',btn('＋ Zapisz przejazd','new-trip','','primary'))+`<section class="card">${toolbar()}${tripTable(filtered(rows('trips'),t=>t.label+' '+name('vehicle_totals',t.vehicle_id)))}</section>`}
function tripTable(arr){return table(['Data / auto','Rajd / przejazd','OS','Dojazdówki','Test szybki / spokojny','Mth','Części'],[...arr].sort((a,b)=>b.at.localeCompare(a.at)).map(t=>[E(t.date)+'<small>'+E(name('vehicle_totals',t.vehicle_id))+'</small>',E(t.label)+'<small>'+E(name('rallies',t.rally_id))+'</small>',num(t.os),num(t.liaison),num(t.fast)+' / '+num(t.low),num(t.hours),btn(rows('part_usage').filter(x=>x.trip_id===t.id).length+' egzemplarzy','trip-detail',t.id,'sm')]))}
function service(){let arr=rows('part_totals').filter(p=>['repair','damaged'].includes(p.state)||dueParts().some(x=>x.id===p.id));return heading('Serwis i limity','Części w naprawie, uszkodzone i z przebiegiem co najmniej 80% limitu.')+`<section class="card">${table(['Część','Stan','Przebieg','Limit','Akcje'],arr.map(p=>[E(partName(p.id)),stateBadge(p.state),mileage(p),num(name('products',p.product_id,'limit_km'))+' km',btn('Historia','part-detail',p.id,'sm')+btn('Serwis / stan','part-action',p.id,'sm')]))}</section><div class="banner">Serwis nie zeruje całkowitego przebiegu egzemplarza. Opis wykonanej naprawy trafia do historii.</div>`}
function shortageTable(arr){return table(['Pozycja','Zakres','Dostępne / minimum','Brak','Zakup'],arr.map((p,i)=>[E(p.name)+'<small>'+E(p.sku)+'</small>',E(p.location),num(p.available)+' / '+num(p.minimum)+' '+E(p.unit),p.missing>0?badge(num(p.missing)+' '+p.unit,'red'):p.available===p.minimum?badge('Na minimum','yellow'):badge('Zapas OK','green'),p.missing>0?btn('Zleć zakup','purchase',p.product_id+'|'+(p.location_id||'global'),'sm'):'—']))}
function shortages(){return heading('Braki i lista zakupów','Minimum globalne oraz osobne minimum np. dla Scanii. Dla części minimum dotyczy nowych egzemplarzy. Używane, zamontowane, zarezerwowane i niesprawne nie zwiększają zapasu nowych.',btn('Pobierz raport CSV','export-shortages')+(manager()?btn('＋ Minimum lokalizacji','new-minimum','','primary'):''))+`<section class="card">${toolbar(locSelect())}${shortageTable(filtered(short(),p=>p.name+' '+p.sku).filter(p=>(!loc||p.location_id===loc)).sort((a,b)=>Number(b.missing)-Number(a.missing)))}</section><div class="banner">Raport pokazuje aktualny stan. Zlecenie zakupu tworzy kartę na tablicy ekipy; ponowne kliknięcie nie tworzy drugiego otwartego zamówienia dla tego samego braku.</div>`}
function taskCard(t){const check=t.checklist||[],done=check.filter(x=>x.done).length;return `<button class="task" data-act="task-detail" data-id="${t.id}">${badge({urgent:'Pilne',high:'Wysoki',normal:'Normalny'}[t.priority],t.priority==='urgent'?'red':t.priority==='high'?'yellow':'')}<div class="task-title">${E(t.title)}</div><div class="task-meta">${t.vehicle_id?E(name('vehicle_totals',t.vehicle_id))+' · ':''}${t.part_id?E(partName(t.part_id)):''}${t.product_id?E(name('products',t.product_id)):''}</div>${check.length?`<div class="progress"><span style="width:${done/check.length*100}%"></span></div>`:''}<div class="actions"><span class="task-meta">${check.length?done+'/'+check.length+' · ':''}${t.due?badge(t.due,t.due<today()&&t.status!=='done'?'red':''): 'Bez terminu'}</span><span class="avatar" title="${E(name('team_members',t.assignee_id))}">${E(name('team_members',t.assignee_id).slice(0,2).toUpperCase())}</span></div></button>`}
function boardPage(){let b=find('boards',board),tasks=filtered(rows('tasks').filter(t=>t.board_id===board),t=>t.title+' '+t.description+' '+name('team_members',t.assignee_id));return heading('Tablica ekipy','Zadania, odpowiedzialne osoby, komentarze, checklisty i dokumenty.',btn('＋ Nowe zadanie','new-task','','primary')+btn('＋ Tablica rajdu','new-board'))+`<div class="toolbar"><select id="board-filter" aria-label="Tablica">${options(rows('boards').map(b=>[b.id,b.name]),board)}</select><input id="search" placeholder="Szukaj zadania lub osoby…" value="${E(search)}">${b?.rally_id?badge(name('rallies',b.rally_id),'blue'):''}</div><div class="board">${Object.entries(statuses).map(([s,l])=>`<section class="column"><h3>${l}<span>${tasks.filter(t=>t.status===s).length}</span></h3>${tasks.filter(t=>t.status===s).map(taskCard).join('')}</section>`).join('')}</div><div class="small muted section">Odświeżanie co minutę i po powrocie do okna. Powiadomienia o przydzieleniu zadania i oznaczeniu osoby znajdziesz w aplikacji.</div>`}
function notifications(){return heading('Powiadomienia','Przydzielone zadania i wzmianki w komentarzach.',btn('Oznacz wszystkie jako przeczytane','seen'))+`<section class="card">${[...rows('notifications')].sort((a,b)=>b.at.localeCompare(a.at)).map(n=>`<div class="note">${!n.seen?badge('Nowe','blue'):''} ${E(n.body)}<small>${stamp(n.at)}</small>${n.task_id?btn('Otwórz zadanie','notification-open',n.id,'sm'):''}</div>`).join('')||'<div class="empty">Nie masz nowych powiadomień.</div>'}</section>`}
function financeRows(t){return rows(t).filter(e=>!financeRally||e.rally_id===financeRally)}
function rallyFilter(){return `<select id="finance-rally"><option value="">Wszystkie rajdy</option>${options(rows('rallies').map(x=>[x.id,x.name]),financeRally)}</select>`}
function expensePLN(e){return Math.round(Number(e.amount)*Number(e.rate)*100)/100}
function expenses(){const arr=filtered(financeRows('expenses'),e=>e.description+' '+name('team_members',e.owner_id));return heading('Wydatki i dokumenty',manager()?'Wgląd we wszystkie rozliczenia.':'Wyłącznie Twoje wydatki i dokumenty.',btn('＋ Wydatek','new-expense','','primary')+btn('Eksport CSV','export-expenses'))+`<section class="card">${toolbar(rallyFilter())}${table(['Data / rajd','Opis / osoba','Kwota','Status','Akcje'],arr.sort((a,b)=>b.date.localeCompare(a.date)).map(e=>[E(e.date)+'<small>'+E(name('rallies',e.rally_id))+'</small>',`<b>${E(e.description)}</b><small>${E(name('team_members',e.owner_id))} · ${E(e.category)}</small>`,num(e.amount)+' '+E(e.currency)+'<small>'+money(expensePLN(e))+'</small>',finBadge(e.status)+(e.reason?'<small>'+E(e.reason)+'</small>':''),btn('Szczegóły','expense-detail',e.id,'sm')]))}</section>`}
function cash(){return heading('Zaliczki, zwroty i refundacje','Zaliczka nie jest kosztem. Wydatki prywatne rozliczamy osobno.',manager()?btn('＋ Zapisz operację','new-cash','','primary'):'')+`<section class="card">${rallyFilter()}${table(['Data / rajd','Osoba','Typ','Kwota PLN','Notatka'],financeRows('cash_entries').sort((a,b)=>b.date.localeCompare(a.date)).map(e=>[E(e.date)+'<small>'+E(name('rallies',e.rally_id))+'</small>',E(name('team_members',e.owner_id)),{advance:'Zaliczka',return:'Zwrot zaliczki',refund:'Refundacja prywatnych'}[e.kind],money(expensePLN(e)),E(e.note)]))}</section>`}
function settlements(){let ex=financeRows('expenses').filter(e=>e.status==='approved'),ca=financeRows('cash_entries'),people=manager()?rows('team_members'): [me];const sum=a=>a.reduce((s,x)=>s+expensePLN(x),0);return heading('Rozliczenia zespołu','Saldo zaliczki = przekazane środki − zatwierdzone wydatki z zaliczki − zwroty.')+`<section class="card">${rallyFilter()}${table(['Osoba','Zaliczki','Wydane z zaliczek','Zwroty','Saldo zaliczki','Prywatne do zwrotu'],people.map(p=>{let a=sum(ca.filter(x=>x.owner_id===p.id&&x.kind==='advance')),spent=sum(ex.filter(x=>x.owner_id===p.id&&x.funding==='advance')),r=sum(ca.filter(x=>x.owner_id===p.id&&x.kind==='return')),pr=sum(ex.filter(x=>x.owner_id===p.id&&x.funding==='private'))-sum(ca.filter(x=>x.owner_id===p.id&&x.kind==='refund'));return [E(p.name),money(a),money(spent),money(r),money(a-spent-r),money(pr)]}))}</section>`}
function rallies(){return heading('Rajdy i budżety','Rajdy łączą przejazdy, finanse i tablice przygotowań.',manager()?btn('＋ Dodaj rajd','new-rally','','primary'):'')+`<div class="grid three">${rows('rallies').map(r=>`<section class="card"><h2>${E(r.name)}</h2><p class="small muted section">${E(r.place)}</p>${manager()?`<div class="metric">${money(rows('rally_budgets').find(x=>x.rally_id===r.id)?.budget)}</div><div class="small muted">Budżet · zatwierdzone koszty: ${money(rows('expenses').filter(e=>e.rally_id===r.id&&e.status==='approved').reduce((s,e)=>s+expensePLN(e),0))}</div>`:'<p class="section small muted">Budżet dostępny dla managera.</p>'}</section>`).join('')||'<div class="card empty">Nie dodano jeszcze rajdów.</div>'}</div>`}
function members(){return heading('Zespół i uprawnienia','Manager dodaje dozwolone adresy. Członek ekipy zakłada i potwierdza konto z dokładnie tym adresem.',btn('＋ Dodaj członka ekipy','new-member','','primary'))+`<section class="card">${table(['Imię i nazwisko','E-mail','Rola','Dostęp','Akcje'],rows('team_members').map(m=>[E(m.name),E(m.email),m.role==='manager'?'Manager':'Pracownik',badge(m.active?'Aktywny':'Wyłączony',m.active?'green':'red'),btn('Edytuj dostęp','edit-member',m.id,'sm')]))}</section>`}
function settings(){return heading('Lokalizacje magazynowe','Możesz dodać bazę, pojazdy, skrzynie i konkretne półki.',btn('＋ Lokalizacja','new-location','','primary'))+`<section class="card">${table(['Nazwa','Stanowiska minimum'],rows('locations').map(l=>[E(l.name),num(rows('stock_minima').filter(x=>x.location_id===l.id).length)]))}</section>`}
function options(items,val='',blank=false){return (blank?'<option value="">— Bez powiązania —</option>':'')+items.map(v=>{let [id,l]=Array.isArray(v)?v:[v,v];return `<option value="${E(id)}" ${String(val)===String(id)?'selected':''}>${E(l)}</option>`}).join('')}
function field(label,key,value='',type='text',extra=''){return `<label>${label}<input name="${key}" value="${E(value)}" type="${type}" ${extra}></label>`}
function select(label,key,items,val='',blank=false){return `<label>${label}<select name="${key}">${options(items,val,blank)}</select></label>`}
function text(label,key,value='',extra=''){return `<label class="wide">${label}<textarea name="${key}" ${extra}>${E(value)}</textarea></label>`}
const opts=t=>rows(t).map(x=>[x.id,x.name]);
const productOpts=(serial=null)=>rows('products').filter(p=>serial===null||p.serialized===serial).map(p=>[p.id,p.sku+' · '+p.name]);
const partOpts=()=>rows('part_totals').map(p=>[p.id,partName(p.id)]);
const peopleOpts=()=>rows('team_members').filter(x=>x.active).map(x=>[x.id,x.name]);
function baseline(){return `<div class="wide formhint">Stan początkowy: wcześniejsze kilometry przed rozpoczęciem ewidencji. Kolejne naliczą się z przejazdów.</div>`+[['OS','base_os'],['Dojazdówki','base_liaison'],['Szybkie testy','base_fast'],['Spokojne testy','base_low'],['Motogodziny','base_hours']].map(([l,k])=>field(l,k,0,'number','required min="0" step="0.001"')).join('')}
function form(title,kind,body,id='',extra=''){modalContext={kind,id};modal.innerHTML=`<div class="spread modalhead"><h2>${E(title)}</h2>${btn('✕','close','','sm')}</div><form id="edit-form"><div class="modalbody"><div class="formgrid">${body}</div>${extra}<div id="form-error" role="alert" class="formhint danger section"></div></div><div class="modalfoot">${btn('Anuluj','close')}<button class="btn primary" type="submit">Zapisz</button></div></form>`;if(!modal.open)modal.showModal()}
function detail(title,body){modalContext=null;modal.innerHTML=`<div class="spread modalhead"><h2>${E(title)}</h2>${btn('✕','close','','sm')}</div><div class="modalbody">${body}</div>`;if(!modal.open)modal.showModal()}
function requireList(t,msg){if(!rows(t).length)throw Error(msg)}
function edit(kind,id='',prefill={}){let x={};switch(kind){
case 'location':form('Nowa lokalizacja','location',field('Nazwa, np. Scania / skrzynia A','name','','text','required maxlength="120"'));break;
case 'vehicle':form('Dodaj samochód','vehicle',field('Numer / kod auta','code','','text','required maxlength="100"')+field('Nazwa auta','name','','text','required maxlength="150"')+baseline());break;
case 'rally':form('Dodaj rajd','rally',field('Nazwa','name','','text','required')+field('Miejsce','place')+field('Budżet PLN','budget',0,'number','required min="0" step="0.01"'));break;
case 'product':x=find('products',id)||{};form(id?'Ustawienia indeksu':'Nowy indeks magazynowy','product',field('Indeks / SKU','sku',x.sku||'','text',`required ${id?'disabled':''}`)+field('Nazwa','name',x.name||'','text','required maxlength="200"')+select('Rodzaj','serialized',[['true','Część numerowana — osobne egzemplarze'],['false','Normalia / materiały — ilości']],String(x.serialized??true))+field('Jednostka','unit',x.unit||'szt.','text',id?'disabled':'required')+field('Minimum całego magazynu','minimum',x.minimum||0,'number','required min="0" step="0.001"')+field('Limit przebiegu egzemplarza (0 = brak)','limit_km',x.limit_km||0,'number','required min="0" step="0.001"')+text('Specyfikacja / wymiar','spec',x.spec||''),id);if(id)modal.querySelector('[name=serialized]').disabled=true;break;
case 'minimum':requireList('products','Najpierw dodaj indeks magazynowy.');form('Minimum dla lokalizacji','minimum',select('Pozycja','product_id',productOpts(),id)+select('Lokalizacja','location_id',opts('locations'),loc)+field('Minimum','minimum',0,'number','required min="0" step="0.001"'));break;
case 'part':requireList('products','Najpierw dodaj typ części w Magazynie.');requireList('locations','Najpierw dodaj lokalizację.');if(!productOpts(true).length)throw Error('Dodaj indeks rodzaju „Część numerowana”.');form('Przyjmij egzemplarz części','part',select('Typ części','product_id',productOpts(true),id)+field('Unikalny numer egzemplarza','serial','','text','required maxlength="150"')+select('Lokalizacja','location_id',opts('locations'),loc)+text('Opis / uwagi','note')+baseline());break;
case 'part_action':x=find('part_totals',id);form('Operacja: '+x.serial,'part_action',select('Operacja','action',x.vehicle_id?[['unmount','Demontaż do magazynu']]:[['mount','Montaż do auta'],['move','Przesunięcie'],['state','Zmiana stanu / serwis']],x.vehicle_id?'unmount':'mount')+select('Auto (montaż)','vehicle_id',opts('vehicle_totals'),'',true)+field('Pozycja montażu, np. półoś lewa','slot')+select('Lokalizacja docelowa (demontaż / przesunięcie)','location_id',opts('locations'),x.location_id)+select('Stan po demontażu / serwisie','state',Object.entries(states),x.state)+text('Opis operacji / naprawy','note','','required maxlength="1000"'),id);break;
case 'stock':x=find('products',id);form('Ruch: '+x.name,'stock',select('Operacja','action',Object.entries(operations).filter(([k])=>['receive','issue','transfer','reserve','release','damage'].includes(k)))+select('Lokalizacja','location_id',opts('locations'),loc)+select('Stan źródłowy / przyjmowany','state',[['ready','Sprawne / dostępne'],['reserved','Zarezerwowane'],['damaged','Uszkodzone']],'ready')+field('Ilość ('+E(x.unit)+')','quantity',1,'number',`required min="0.001" step="${x.unit==='szt.'?'1':'0.001'}"`)+select('Lokalizacja docelowa — przesunięcie','to_location',opts('locations'),'',true)+text('Cel / opis ruchu','note','','required maxlength="1000"'),id,'<div class="banner">Rezerwacja i uszkodzenie pobierają stan dostępny. Zwolnienie rezerwacji przywraca dostępny zapas.</div>');break;
case 'trip':requireList('vehicle_totals','Najpierw dodaj samochód.');form('Zapisz przejazd','trip',select('Samochód','vehicle_id',opts('vehicle_totals'),id)+field('Data jazdy — dzisiaj','date',today(),'date','required readonly')+field('Nazwa, np. OS1 / test zawieszenia','label','','text','required')+select('Rodzaj jazdy','type',[['rally','Rajd: OS + dojazdówki'],['test','Trening / test: szybki + spokojny'],['travel','Dojazd: kilometry dojazdowe']])+select('Rajd — wymagany dla jazdy rajdowej','rally_id',opts('rallies'),'',true)+[['OS km','os'],['Dojazdówki km','liaison'],['Test szybki km','fast'],['Test spokojny km','low'],['Motogodziny','hours']].map(([l,k])=>field(l,k,0,'number','required min="0" step="0.001"')).join(''),'','<div class="banner">Wpis naliczy przebieg częściom zamontowanym w chwili zapisu. Sprawdź zestaw części przed zatwierdzeniem. Wpisów przejazdów nie edytujemy ani nie usuwamy.</div>');break;
case 'board':form('Nowa tablica','board',field('Nazwa tablicy','name','','text','required')+select('Powiązany rajd','rally_id',opts('rallies'),'',true));break;
case 'task':requireList('boards','Najpierw dodaj tablicę.');x=find('tasks',id)||prefill;form(id?'Edytuj zadanie':'Nowe zadanie','task',select('Tablica','board_id',opts('boards'),x.board_id||board)+field('Tytuł','title',x.title||'','text','required maxlength="220"')+select('Status','status',Object.entries(statuses),x.status||'todo')+select('Priorytet','priority',[['normal','Normalny'],['high','Wysoki'],['urgent','Pilny']],x.priority||'normal')+select('Odpowiedzialna osoba','assignee_id',peopleOpts(),x.assignee_id||'',true)+field('Termin','due',x.due||'','date')+select('Samochód','vehicle_id',opts('vehicle_totals'),x.vehicle_id||'',true)+select('Egzemplarz części','part_id',partOpts(),x.part_id||'',true)+select('Indeks magazynowy','product_id',productOpts(),x.product_id||'',true)+text('Opis','description',x.description||'')+text('Lista kontrolna — jeden punkt w wierszu','checklist_text',(x.checklist||[]).map(c=>(c.done?'[x] ':'[ ] ')+c.text).join('\n'))+field('Ilość do zakupu (opcjonalnie)','buy_quantity',x.buy_quantity||'','number','min="0.001" step="0.001"'),id);modalContext.prefill=x;break;
case 'member':x=find('team_members',id)||{};form(id?'Dostęp członka ekipy':'Dodaj członka ekipy','member',field('Imię i nazwisko','name',x.name||'','text','required maxlength="120"')+field('Adres e-mail','email',x.email||'','email',`required ${id?'disabled':''}`)+select('Rola','role',[['member','Pracownik'],['manager','Manager — wszystkie finanse']],x.role||'member')+select('Dostęp','active',[['true','Aktywny'],['false','Wyłączony']],String(x.active??true)),id);break;
case 'expense':requireList('rallies','Manager musi najpierw dodać rajd.');x=find('expenses',id)||{};form(id?'Edytuj wydatek':'Dodaj wydatek','expense',(manager()?select('Osoba','owner_id',peopleOpts(),x.owner_id||me.id):'')+select('Rajd','rally_id',opts('rallies'),x.rally_id||financeRally)+field('Data','date',x.date||today(),'date','required')+field('Opis','description',x.description||'','text','required maxlength="220"')+select('Kategoria','category',['Paliwo','Transport','Części','Serwis','Wpisowe','Noclegi','Wyżywienie','Inne'],x.category||'Części')+field('Kwota','amount',x.amount||'','number','required min="0.01" step="0.01"')+select('Waluta','currency',['PLN','EUR','USD','MAD'],x.currency||'PLN')+field('Kurs do PLN','rate',x.rate||1,'number','required min="0.000001" step="0.000001"')+select('Źródło płatności','funding',[['advance','Zaliczka'],['private','Prywatne środki'],['company','Środki firmowe']],x.funding||'advance'),id);break;
case 'cash':requireList('rallies','Najpierw dodaj rajd.');form('Operacja rozliczeniowa','cash',select('Osoba','owner_id',peopleOpts())+select('Rajd','rally_id',opts('rallies'),financeRally)+select('Rodzaj','kind',[['advance','Zaliczka dla pracownika'],['return','Zwrot niewykorzystanej zaliczki'],['refund','Refundacja wydatków prywatnych']])+field('Data','date',today(),'date','required')+field('Kwota','amount','','number','required min="0.01" step="0.01"')+select('Waluta','currency',['PLN','EUR','USD','MAD'],'PLN')+field('Kurs do PLN','rate',1,'number','required min="0.000001" step="0.000001"')+text('Opis','note'));break;
case 'password':form('Zmień hasło','password',field('Nowe hasło — min. 12 znaków','password','','password','required minlength="12" autocomplete="new-password"')+field('Powtórz hasło','repeat','','password','required minlength="12" autocomplete="new-password"'));break;
}}
function docsFor(kind,id){const docs=rows('documents').filter(d=>d[kind+'_id']===id);return `<div class="attachments"><h3>Dokumenty i zdjęcia</h3>${docs.map(d=>btn(E(d.name),'download',d.id,'sm')).join('')||'<p class="small muted section">Brak załączników.</p>'}<label class="small section" style="display:block">Dodaj PDF lub zdjęcie (do 8 MB)<input type="file" data-upload="${kind}" data-id="${id}" accept="application/pdf,image/jpeg,image/png,image/webp,image/heic" style="display:block;margin-top:8px"></label></div>`}
function showPart(id){const p=find('part_totals',id),pr=find('products',p.product_id);detail(partName(id),`<div class="spread"><div>${stateBadge(p.state)}<div class="section">${wherePart(p)}</div></div>${mileage(p)}</div><div class="banner">Limit: ${pr.limit_km?num(pr.limit_km)+' km':'Nie ustalono'} · Stan początkowy: ${num(Number(p.base_os)+Number(p.base_liaison)+Number(p.base_fast)+Number(p.base_low))} km<br>${E(p.note)}</div>${btn('Montaż / magazyn / serwis','part-action',id,'primary')}<h3 class="section">Historia operacji</h3>${movementTable(rows('movements').filter(m=>m.part_id===id))}<h3 class="section">Historia przejazdów</h3>${tripTable(rows('trips').filter(t=>rows('part_usage').some(u=>u.trip_id===t.id&&u.part_id===id)))}`)}
function showVehicle(id){const v=find('vehicle_totals',id);detail(v.name,`<div class="eyebrow">${E(v.code)}</div>${mileage(v)}<div class="section">${btn('＋ Przejazd','new-trip',id,'primary')}</div><h3 class="section">Zamontowane egzemplarze</h3>${table(['Pozycja','Część','Przebieg','Karta'],rows('part_totals').filter(p=>p.vehicle_id===id).map(p=>[E(p.slot),E(partName(p.id)),mileage(p),btn('Historia','part-detail',p.id,'sm')]))}<h3 class="section">Przejazdy auta</h3>${tripTable(rows('trips').filter(t=>t.vehicle_id===id))}`)}
function showTask(id){const t=find('tasks',id);detail(t.title,`<div class="spread">${badge(statuses[t.status],'blue')}${btn('Edytuj kartę','edit-task',id,'primary')}</div><p class="section small" style="white-space:pre-wrap">${E(t.description)}</p><div class="banner">Odpowiedzialny: <b>${E(name('team_members',t.assignee_id))}</b> · Termin: ${E(t.due||'Nie ustalono')}<br>Auto: ${E(name('vehicle_totals',t.vehicle_id))} · Część: ${E(partName(t.part_id))} · Indeks: ${E(name('products',t.product_id))}${t.buy_quantity?'<br>Do zakupu: '+num(t.buy_quantity):''}</div>${(t.checklist||[]).map((c,i)=>`<label class="check"><input type="checkbox" data-check-task="${t.id}" data-index="${i}" ${c.done?'checked':''}>${E(c.text)}</label>`).join('')}${docsFor('task',id)}<h3 class="section">Rozmowa przy zadaniu</h3>${rows('comments').filter(c=>c.task_id===id).sort((a,b)=>a.at.localeCompare(b.at)).map(c=>`<div class="note"><b>${E(name('team_members',c.actor_id))}</b><small>${stamp(c.at)}</small><span style="white-space:pre-wrap">${E(c.body)}</span></div>`).join('')||'<p class="small muted section">Dodaj pierwszy komentarz.</p>'}<form id="comment-form" data-id="${id}" class="grid section"><textarea name="body" required maxlength="4000" placeholder="Napisz do ekipy…" aria-label="Komentarz"></textarea><label class="small">Oznacz osoby (Ctrl/Cmd, aby wybrać kilka)<select name="mentions" multiple style="display:block;width:100%;margin-top:7px">${options(peopleOpts())}</select></label><button class="btn primary" type="submit">Dodaj komentarz</button><div class="danger small" data-comment-error role="alert"></div></form>`)}
function showExpense(id){const e=find('expenses',id);detail(e.description,`${finBadge(e.status)}<div class="metric">${money(expensePLN(e))}</div><div class="banner">${E(e.date)} · ${E(name('rallies',e.rally_id))}<br>${E(name('team_members',e.owner_id))} · ${num(e.amount)} ${E(e.currency)} · kurs ${num(e.rate)}<br>${E(e.reason)}</div><div class="actions">${e.status!=='approved'?btn('Edytuj','edit-expense',id):''}${manager()&&e.status!=='approved'?btn('Zatwierdź','approve',id,'primary')+btn('Do poprawy','reject',id):''}${e.status!=='approved'?btn('Usuń bez dokumentów','delete-expense',id,'danger'):''}</div>${e.status==='approved'?'<h3 class="section">Dokumenty</h3>'+rows('documents').filter(d=>d.expense_id===id).map(d=>btn(E(d.name),'download',d.id,'sm')).join(''):docsFor('expense',id)}`)}
function authScreen(mode='login',message=''){me=null;root.innerHTML=`<div class="auth"><div class="authwrap"><div class="brand"><div class="mark">AK</div><div><b>AKPOL</b><span>RALLY TEAM</span></div></div><section class="card"><div class="eyebrow">ONE TEAM ONE GOAL</div><h1>${mode==='register'?'Aktywuj swoje konto':mode==='recover'?'Odzyskaj dostęp':'Witaj w zespole'}</h1><p>${mode==='register'?'Użyj adresu dodanego przez managera. Potwierdź e-mail przed pierwszym logowaniem.':mode==='recover'?'Wyślemy na Twój adres link do ustawienia nowego hasła.':'Samochody, części, magazyn i praca ekipy. Zaloguj się swoim kontem.'}</p>${message?`<div class="banner">${E(message)}</div>`:''}<form id="auth-form" data-mode="${mode}"><label>E-mail<input type="email" name="email" required autocomplete="username"></label>${mode!=='recover'?'<label>Hasło<input type="password" name="password" required '+(mode==='register'?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"')+'></label>':''}<button type="submit" class="btn primary">${mode==='login'?'Zaloguj się →':mode==='register'?'Utwórz konto':'Wyślij link'}</button><div class="danger small" id="auth-error" role="alert"></div></form><div class="flex section"><button class="subtlelink" data-auth-mode="${mode==='login'?'register':'login'}">${mode==='login'?'Pierwsze logowanie? Aktywuj konto':'Wróć do logowania'}</button>${mode==='login'?'<button class="subtlelink" data-auth-mode="recover">Nie pamiętam hasła</button>':''}</div></section><p class="authfoot">Dostęp do danych przydziela manager.<br>Każdy pracownik widzi wyłącznie własne wydatki.</p></div></div>`}
function serialize(form){return Object.fromEntries(new FormData(form).entries())}
function csv(filename,headers,arr){const cell=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const out='\ufeff'+[headers,...arr].map(r=>r.map(cell).join(';')).join('\r\n');downloadBlob(new Blob([out],{type:'text/csv;charset=utf-8'}),filename)}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function fileUpload(kind,id,file){if(!file)return;if(file.size>8388608)throw Error('Maksymalny rozmiar pliku to 8 MB.');const types=['application/pdf','image/jpeg','image/png','image/webp','image/heic'];if(!types.includes(file.type))throw Error('Wybierz PDF, JPG, PNG, WEBP lub HEIC.');let path=id+'/'+user.id+'/'+crypto.randomUUID(),bucket=kind==='expense'?'akpol-finance':'akpol-team';await request('/storage/v1/object/'+bucket+'/'+path,{method:'POST',body:file,headers:{'Content-Type':file.type,'x-upsert':'false'}});try{await command('document',{[kind+'_id']:id,path,name:file.name})}catch(e){throw Error('Plik przesłano, ale nie udało się przypisać go do wpisu: '+e.message)}await sync(false);kind==='expense'?showExpense(id):showTask(id);toast('Załącznik dodany.')}
async function actions(a,id){switch(a){
case 'nav':nav=!nav;render();break;
case 'close':modal.close();break;
case 'sync':await sync();toast('Dane odświeżone.');break;
case 'logout':try{await auth('logout',{})}finally{saveSession(null);data={};user=null;modal.close();authScreen()}break;
case 'password':edit('password');break;
case 'go-shortages':page='shortages';render();break;
case 'go-board':page='board';render();break;
case 'new-vehicle':edit('vehicle');break;
case 'new-location':edit('location');break;
case 'new-product':edit('product');break;
case 'edit-product':edit('product',id);break;
case 'product-detail':{let p=find('products',id);detail(p.name,`<div class="banner">${E(p.sku)} · ${E(p.spec)} · Minimum globalne ${num(p.minimum)} ${E(p.unit)}</div>${table(['Lokalizacja','Sprawne','Rezerwacja','Uszkodzone / inne'],rows('locations').map(l=>{let st=rows('stock').filter(x=>x.product_id===id&&x.location_id===l.id),pa=rows('part_totals').filter(x=>x.product_id===id&&x.location_id===l.id);return [E(l.name),num(p.serialized?pa.filter(x=>x.state==='ready'&&(!p.limit_km||x.km<p.limit_km)).length:st.find(x=>x.state==='ready')?.quantity),num(p.serialized?pa.filter(x=>x.state==='reserved').length:st.find(x=>x.state==='reserved')?.quantity),num(p.serialized?pa.filter(x=>!['ready','reserved'].includes(x.state)).length:st.find(x=>x.state==='damaged')?.quantity)]}))}${p.serialized?table(['Egzemplarz','Miejsce','Przebieg'],rows('part_totals').filter(x=>x.product_id===id).map(x=>[btn(E(x.serial),'part-detail',x.id,'sm'),wherePart(x),mileage(x)])):''}<h3 class="section">Historia ruchów</h3>${movementTable(rows('movements').filter(x=>x.product_id===id))}`);break}
case 'new-minimum':edit('minimum');break;
case 'new-part':edit('part',id);break;
case 'part-action':edit('part_action',id);break;
case 'stock-action':edit('stock',id);break;
case 'new-trip':edit('trip',id);break;
case 'part-detail':showPart(id);break;
case 'vehicle-detail':showVehicle(id);break;
case 'trip-detail':{let t=find('trips',id);detail(t.label,`<div class="banner">${E(t.date)} · ${E(name('vehicle_totals',t.vehicle_id))}<br>OS ${num(t.os)} km · Dojazdówki ${num(t.liaison)} km · Testy ${num(t.fast)} + ${num(t.low)} km</div>${table(['Egzemplarze, którym naliczono przebieg'],rows('part_usage').filter(x=>x.trip_id===id).map(x=>[btn(E(partName(x.part_id)),'part-detail',x.part_id,'sm')]))}`);break}
case 'new-board':edit('board');break;
case 'new-task':edit('task');break;
case 'edit-task':edit('task',id);break;
case 'task-detail':showTask(id);break;
case 'purchase':{const [pid,scope]=id.split('|'),s=short().find(x=>x.product_id===pid&&(x.location_id||'global')===scope);let t=rows('tasks').find(x=>x.product_id===pid&&x.buy_scope===scope&&x.status!=='done');if(t){showTask(t.id);break}edit('task','',{title:'Zakup: '+s.name+' · '+num(s.missing)+' '+s.unit,description:'Uzupełnij zapas: '+s.location+'. Dostępne: '+num(s.available)+', minimum: '+num(s.minimum)+'. Ilość należy zweryfikować przed zamówieniem.',product_id:pid,buy_scope:scope,buy_quantity:s.missing,priority:'high'});break}
case 'seen':await command('notification_seen',{});await sync();break;
case 'notification-open':{let n=find('notifications',id);await command('notification_seen',{id});await sync(false);showTask(n.task_id);render();break}
case 'new-rally':edit('rally');break;
case 'new-member':edit('member');break;
case 'edit-member':edit('member',id);break;
case 'new-expense':edit('expense');break;
case 'edit-expense':edit('expense',id);break;
case 'expense-detail':showExpense(id);break;
case 'approve':if(confirm('Zatwierdzić wydatek i zablokować jego edycję?')){await command('expense_review',{id,status:'approved'});await sync(false);showExpense(id);render()}break;
case 'reject':{let reason=prompt('Podaj powód zwrócenia do poprawy:');if(reason?.trim()){await command('expense_review',{id,status:'rejected',reason});await sync(false);showExpense(id);render()}break}
case 'delete-expense':if(confirm('Usunąć niezatwierdzony wydatek bez dokumentów?')){await command('expense_delete',{id});modal.close();await sync()}break;
case 'new-cash':edit('cash');break;
case 'download':{const d=find('documents',id);if(!d)throw Error('Brak dostępu do dokumentu');const r=await request('/storage/v1/object/authenticated/'+(d.expense_id?'akpol-finance':'akpol-team')+'/'+d.path);downloadBlob(await r.blob(),d.name);break}
case 'export-shortages':csv('AKPOL_braki_'+today()+'.csv',['Indeks','Nazwa','Lokalizacja','Dostępne','Minimum','Brak','Jednostka'],short().filter(x=>x.available<=x.minimum).map(x=>[x.sku,x.name,x.location,x.available,x.minimum,x.missing,x.unit]));break;
case 'export-expenses':csv('AKPOL_wydatki_'+today()+'.csv',['Data','Osoba','Rajd','Opis','Kwota','Waluta','Kurs','PLN','Status'],financeRows('expenses').map(x=>[x.date,name('team_members',x.owner_id),name('rallies',x.rally_id),x.description,x.amount,x.currency,x.rate,expensePLN(x),x.status]));break;
}}
document.addEventListener('click',e=>{const pg=e.target.closest('[data-page]');if(pg){page=pg.dataset.page;search='';loc='';nav=false;render();return}let am=e.target.closest('[data-auth-mode]');if(am){authScreen(am.dataset.authMode);return}let b=e.target.closest('[data-act]');if(!b)return;if(b.disabled)return;b.disabled=true;actions(b.dataset.act,b.dataset.id).catch(x=>toast(x.message,true)).finally(()=>b.disabled=false)});
document.addEventListener('submit',async e=>{const f=e.target;if(!['auth-form','edit-form','comment-form'].includes(f.id))return;e.preventDefault();if(busy)return;busy=true;const button=f.querySelector('[type=submit]');button.disabled=true;try{let d=serialize(f);
 if(f.id==='auth-form'){const mode=f.dataset.mode;document.querySelector('#auth-error').textContent='';if(mode==='register'){await auth('signup',{email:d.email,password:d.password});authScreen('login','Konto zarejestrowane. Sprawdź pocztę, potwierdź adres e-mail i zaloguj się.')}else if(mode==='recover'){await auth('recover?redirect_to='+encodeURIComponent(location.href.split('#')[0]),{email:d.email});authScreen('login','Jeśli konto istnieje, otrzymasz wiadomość z linkiem odzyskiwania dostępu.')}else{saveSession(await auth('token?grant_type=password',d));user=await auth('user');await sync()}}
 else if(f.id==='comment-form'){const mentions=[...f.elements.mentions.selectedOptions].map(x=>x.value),id=f.dataset.id;await command('comment',{task_id:id,body:d.body,mentions});await sync(false);showTask(id)}
 else{const {kind,id,prefill}=modalContext;let result;if(kind==='password'){if(d.password!==d.repeat)throw Error('Hasła nie są takie same.');await request('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:d.password})});modal.close();toast('Hasło zmienione.');return}if(id)d.id=id;
 if(kind==='product'&&!id)d.serialized=d.serialized==='true';if(kind==='member')d.active=d.active==='true';
 if(kind==='part_action'&&d.action==='mount'&&!d.vehicle_id)throw Error('Wybierz samochód do montażu.');
 if(kind==='task'){d.checklist=d.checklist_text.split('\n').map(t=>t.trim()).filter(Boolean).map(t=>({text:t.replace(/^\[[ xX]\]\s*/,''),done:/^\[[xX]\]/.test(t)}));delete d.checklist_text;if(id){d.version=find('tasks',id).version;delete d.board_id}else if(prefill?.buy_scope)d.buy_scope=prefill.buy_scope;}
 if(kind==='stock'){d.product_id=id;delete d.id}if(kind==='trip'&& !confirm('Potwierdzasz przejazd i aktualny zestaw zamontowanych części?'))return;
 result=await command(kind,d);modal.close();await sync();toast('Zapisano.');if(kind==='task')showTask(result.id);}
 }catch(x){let err=f.querySelector('#auth-error,#form-error,[data-comment-error]');if(err)err.textContent=x.message;else toast(x.message,true)}finally{busy=false;if(button.isConnected)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;search=e.target.value;render();let f=document.querySelector('#search');if(f){f.focus();f.setSelectionRange(pos,pos)}}});
document.addEventListener('change',async e=>{try{const t=e.target;if(t.id==='location-filter'){loc=t.value;render()}if(t.id==='board-filter'){board=t.value;render()}if(t.id==='finance-rally'){financeRally=t.value;render()}if(t.dataset.upload){t.disabled=true;try{await fileUpload(t.dataset.upload,t.dataset.id,t.files[0])}finally{t.disabled=false}}
 if(t.dataset.checkTask){t.disabled=true;const task=find('tasks',t.dataset.checkTask),checklist=task.checklist.map((c,i)=>i===Number(t.dataset.index)?{...c,done:t.checked}:c);await command('task',{...task,checklist});await sync(false);showTask(task.id);render()}
 }catch(x){toast(x.message,true);if(e.target.dataset.checkTask){await sync(false);showTask(e.target.dataset.checkTask)}}});
window.addEventListener('focus',()=>{if(me&&!modal.open&&!busy)sync().catch(e=>toast(e.message,true))});
setInterval(()=>{if(me&&!document.hidden&&!modal.open&&!busy)sync().catch(e=>toast('Nie udało się odświeżyć: '+e.message,true))},60000);
(async()=>{try{let recovery=false;const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('access_token')){saveSession({access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token'),expires_at:Math.floor(Date.now()/1000)+Number(hash.get('expires_in')||3600)});recovery=hash.get('type')==='recovery';history.replaceState(null,'',location.pathname+location.search)}else{try{session=JSON.parse(localStorage.getItem('akpol-cloud-session')||sessionStorage.getItem('akpol-cloud-session'))}catch{saveSession(null)}}if(!session){authScreen();return}await token();user=await auth('user');await sync();if(recovery)edit('password')}catch(e){saveSession(null);authScreen('login',e.message)}})();
